class Solution:
 def countTime(self, time):
  h,m=time.split(':')
  hours=sum(1 for x in range(24) if all(a=='?' or a==b for a,b in zip(h,f'{x:02d}')))
  minutes=sum(1 for x in range(60) if all(a=='?' or a==b for a,b in zip(m,f'{x:02d}')))
  return hours*minutes

class Solution:
 def findMaxK(self, nums):
  seen=set(nums)
  return max((x for x in seen if x>0 and -x in seen),default=-1)

class Solution:
 def haveConflict(self, event1, event2):
  return event1[0] <= event2[1] and event2[0] <= event1[1]

class Solution:
 def oddString(self, words):
  def sig(w): return tuple(ord(w[i+1])-ord(w[i]) for i in range(len(w)-1))
  counts={}
  for w in words: counts[sig(w)]=counts.get(sig(w),0)+1
  for w in words:
   if counts[sig(w)]==1: return w

class Solution:
 def applyOperations(self, nums):
  a=nums[:]
  for i in range(len(a)-1):
   if a[i]==a[i+1]: a[i]*=2; a[i+1]=0
  nonzero=[x for x in a if x!=0]
  return nonzero+[0]*(len(a)-len(nonzero))

class Solution:
 def distinctAverages(self, nums):
  a=sorted(nums)
  return len({a[i]+a[-1-i] for i in range(len(a)//2)})

class Solution:
 def unequalTriplets(self, nums):
  n=len(nums)
  return sum(1 for i in range(n) for j in range(i+1,n) for k in range(j+1,n) if nums[i]!=nums[j] and nums[i]!=nums[k] and nums[j]!=nums[k])

class Solution:
 def numberOfCuts(self, n):
  if n==1: return 0
  return n//2 if n%2==0 else n

class Solution:
 def pivotInteger(self, n):
  total=n*(n+1)//2
  x=int(total**0.5)
  return x if x*x==total else -1

class Solution:
 def isCircularSentence(self, sentence):
  words=sentence.split()
  return all(words[i][-1]==words[(i+1)%len(words)][0] for i in range(len(words)))
